```ts
interface Database {
  insert(table: string, row: unknown): Promise<void>;
}

class OrderService {
  constructor(private db: Database) {}  // injected

  async save(order: Order) {
    await this.db.insert("orders", order);
  }
}

// Production wiring
const service = new OrderService(new PostgresClient("postgres://..."));

// Test wiring
const fake: Database = { insert: async () => {} };
